list_discount_profiles.code:
use WebCommander\Sdk\Resources\DiscountProfiles\DiscountProfiles;

$response = DiscountProfiles::listDiscountProfiles($client, ['sort' => 'name', 'dir' => 'asc']);

foreach ($response->map['discount_profiles'] as $profile) {
    echo $profile['id'], ' ', $profile['name'], ' ', $profile['type'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' discount profiles in total', PHP_EOL;

create_discount_profile.code:
use WebCommander\Sdk\Resources\DiscountProfiles\DiscountProfiles;
$response = DiscountProfiles::createDiscountProfile($client, [
    'name' => 'Spring 40 Off', 'type' => 'offer_coupon', 'discount_details_type' => 'amount',
    'amount_details' => ['type' => 'single', 'apply_to' => 'total_order', 'single_amount' => 40, 'single_amount_type' => 'PERCENT'],
    'is_active' => true, 'start_date' => '2026-11-06 09:30:00', 'is_specify_end_date' => true,
    'end_date' => '2026-11-16 18:00:00', 'is_apply_coupon_code' => true, 'default_coupon_code' => 'SPRING40', 'is_maximum_use_total' => true,
    'maximum_use_count' => 100, 'is_maximum_use_customer' => true, 'maximum_use_customer_count' => 1, 'is_maximum_discount_allowed' => true,
    'maximum_discount_allowed_amount' => 200, 'is_display_text_coupon' => true, 'display_text_coupon' => 'Use code SPRING40 at checkout',
