get_discount_profile.code:
use WebCommander\Sdk\Resources\DiscountProfiles\DiscountProfiles;

$response = DiscountProfiles::getDiscountProfile($client, 1001);

$profile = $response->map['discount_profile'];
echo $profile['name'], ' ', $profile['default_coupon_code'], PHP_EOL;
foreach ($profile['customer_coupons'] as $coupon) {
    echo $coupon['code'], ' ', $coupon['customer_email'] ?: 'unassigned', PHP_EOL;
}

update_discount_profile.code:
use WebCommander\Sdk\Resources\DiscountProfiles\DiscountProfiles;
